import{_ as e,o as t,c as l,aw as a}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Наследование","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/programming/oop-principles/inheritance.md","filePath":"wiki/dev-commit/theory/programming/oop-principles/inheritance.md"}'),o={name:"wiki/dev-commit/theory/programming/oop-principles/inheritance.md"};function r(s,i,n,c,p,m){return t(),l("div",null,[...i[0]||(i[0]=[a('<h1 id="наследование" tabindex="-1">Наследование <a class="header-anchor" href="#наследование" aria-label="Permalink to &quot;Наследование&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Наследование</p><ul><li><strong>Наследование</strong> - описание нового класса на основе уже существующего с частично или полностью заимствующейся функциональностью</li></ul></div><ul><li>Наследование транзитивно: класс может наследоваться от другого класса, который наследуется от третьего, и так далее вплоть до базового класса (Object). Наследник может переопределить какие-то методы и поля чтобы изменить поведение по умолчанию</li><li><em>SuperClass</em>: базовый, родительский, предок, надкласс, супер класс</li><li><em>SubClass</em>: наследник, дочерний, потомок, подкласс, суб класс, производный</li><li>Подкласс должен являться более специализированной версией супер-класса</li></ul><div class="tip custom-block"><p class="custom-block-title">Множественное наследование</p><ul><li><strong>Множественное наследование</strong> - у одного подкласса существует сразу несколько супер-классов</li></ul></div><h2 id="использование" tabindex="-1">Использование <a class="header-anchor" href="#использование" aria-label="Permalink to &quot;Использование&quot;">​</a></h2><p><strong>Использовать</strong></p><ul><li>Класс-потомок использует большинство свойств и методов базового класса</li><li>С классом-потомком удобно работать по принципам SOLID</li></ul><p><strong>Не использовать</strong></p><ul><li>Реализация класса-потомка сильно отличается от наследуемого класса</li><li>Приходится переопределять методы и свойства у класса-потомка (что некорректно по SOLID)</li><li>Класс-потомок не использует методы и свойства из базового класса или их использование крайне мало</li></ul>',10)])])}const h=e(o,[["render",r]]);export{u as __pageData,h as default};
